#!/bin/sh
# Renders assets/icon/icon.svg to the iOS and Android launcher icons.
# Needs rsvg-convert (librsvg). Run from runner-remote/.
set -eu
src=assets/icon/icon.svg
android=assets/icon/icon-android.svg
ios=ios/Runner/Assets.xcassets/AppIcon.appiconset

# Android (no adaptive icon): a rounded square with a margin, as launchers
# show legacy icons as they are.
python3 - "$src" "$android" <<'PY'
import re, sys
svg = open(sys.argv[1]).read()
body = re.search(r'<svg[^>]*>(.*)</svg>', svg, re.S).group(1)
open(sys.argv[2], 'w').write(f'''<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by tool/icons.sh from icon.svg; edit that instead. -->
<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024">
  <defs><clipPath id="round"><rect width="1024" height="1024" rx="230"/></clipPath></defs>
  <g transform="translate(80 80) scale(0.84375)" clip-path="url(#round)">{body}</g>
</svg>
''')
PY
for pair in mdpi:48 hdpi:72 xhdpi:96 xxhdpi:144 xxxhdpi:192; do
  rsvg-convert -w "${pair#*:}" -h "${pair#*:}" "$android" \
    -o "android/app/src/main/res/mipmap-${pair%%:*}/ic_launcher.png"
done

# iOS: full-bleed and opaque; the system rounds the corners.
for file in "$ios"/Icon-App-*.png; do
  name=${file##*/Icon-App-}
  size=${name%%x*}
  scale=${name##*@}; scale=${scale%x.png}
  px=$(python3 -c "print(round($size*$scale))")
  rsvg-convert -w "$px" -h "$px" -b '#0B0C0D' "$src" -o "$file"
done
echo "icons rendered"
